def gerar_look(sexo, papel=None, idade=35, rng=random):
    est = rng.choice(["longo", "cacheado", "coque", "rabo", "longo", "curto"] if sexo == "F" else ["curto", "curto", "careca", "cacheado", "curto"])
    roupa = ROUPA_PAPEL.get(papel) or ("vestido" if sexo == "F" and rng.random() < .55 else rng.choice(["casual", "social"]))
    cab_cor = "#9e9e9e" if idade > 55 else rng.choice(["#1a1a1a", "#3b2a1a", "#3b2a1a", "#8d5524", "#e6c27a"])
    cor = (rng.choice(["#263238", "#1a237e", "#37474f", "#212121", "#4e342e"]) if roupa == "terno"
           else rng.choice(["#1e88e5", "#c62828", "#2e7d32", "#6a1b9a", "#ef6c00", "#00838f", "#ad1457", "#fafafa"]))
    return dict(sexo=sexo, pele=rng.choice(PELES), cab=est, cab_cor=cab_cor, roupa=roupa, cor=cor,
                calca=rng.choice(["#37474f", "#212121", "#1a237e", "#5d4037"]), idade=idade,
                gravata=rng.choice(["#c62828", "#1565c0", "#6a1b9a", "#2e7d32"]))


def look_de(p):
    if "look" not in p:
        p["look"] = gerar_look(p["sexo"], p["papel"], p["idade"], random.Random(p["id"] + p["nome"]))
    L = dict(p["look"])
    L["nome"] = p["nome"]
    return L


def look_jogador(e):
    L = dict(e.get("look") or gerar_look("M", None, 30, random.Random(e["jogador"])))
    if e["fase_max"] >= 3 and L.get("roupa") in ("casual", None):
        L["roupa"] = "terno" if L.get("sexo") == "M" else "social"
    return L


def npcs_do_texto(e, texto, eid=None):
    vistos, out = set(), []
    for p in sorted(e["pessoas"].values(), key=lambda p: -p["conheceu"]):
        if p["nome"] in texto and p["nome"] not in vistos:
            vistos.add(p["nome"])
            out.append(look_de(p))
    if not out and eid in GENERICOS:
        for k, (nome, sexo, roupa) in enumerate(GENERICOS[eid]):
            L = gerar_look(sexo, None, 40, random.Random(eid + str(k)))
            L.update(roupa=roupa, nome=nome)
            out.append(L)
    return out[:3]


def md_html(t):
    import html as _h
    import re as _re
    t = _h.escape(t)
    t = _re.sub(r"\*\*(.+?)\*\*", r"<b>\1</b>", t)
    t = _re.sub(r"\*(.+?)\*", r"<i>\1</i>", t)
    return t.replace("\n", "<br>")


VOZ_JS = r"""
// ---------- voz (narração com a voz do navegador; o botão 🗣️ liga e desliga em todos os jogos)
let vozOn = true; try { vozOn = localStorage.getItem('voz_on') !== '0'; } catch (e) {}
let _vozes = [], _ultFala = '', _ultFalaT = 0, _ultTela = '';
function _carregarVozes(){ try { _vozes = speechSynthesis.getVoices(); } catch (e) {} }
if ('speechSynthesis' in window) { _carregarVozes(); try { speechSynthesis.addEventListener('voiceschanged', _carregarVozes); } catch (e) {} }
function vozPt(i){ let l = _vozes.filter(v => /^pt[-_]BR/i.test(v.lang)); if (!l.length) l = _vozes.filter(v => /^pt/i.test(v.lang)); return l.length ? l[Math.abs(i || 0) % l.length] : null; }
function falar(txt, o = {}){ return; if (!vozOn || (typeof mudo !== 'undefined' && mudo) || !('speechSynthesis' in window) || !txt) return;
  txt = String(txt).replace(/<[^>]*>/g, ' ').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{200D}★✚✖●⏱]/gu, '').replace(/\s+/g, ' ').trim().slice(0, 260);
  if (!txt) return; const agora = Date.now(); if (txt === _ultFala && agora - _ultFalaT < 5000) return; _ultFala = txt; _ultFalaT = agora;
  try { if (!o.fila) speechSynthesis.cancel(); const u = new SpeechSynthesisUtterance(txt); u.lang = 'pt-BR'; const v = vozPt(o.voz); if (v) u.voice = v;
    u.rate = o.rate || 1.05; u.pitch = o.pitch || 1; u.volume = o.vol == null ? 1 : o.vol; speechSynthesis.speak(u); } catch (e) {} }
function falarTela(el){ if (!el) return; const h = el.querySelector('h1, h2'), p = el.querySelector('.grande') || el.querySelector('p'); const t = (h ? h.textContent : '') + (p ? '. ' + p.textContent : '');
  if (t && t !== _ultTela) { const prim = !_ultTela; _ultTela = t; if (prim) return; falar(t, {rate: 1.08}); } }
function alternarVoz(){ vozOn = !vozOn; try { localStorage.setItem('voz_on', vozOn ? '1' : '0'); } catch (e) {} try { if (!vozOn) speechSynthesis.cancel(); } catch (e) {} if (vozOn) { _ultFala = ''; falar('Voz ligada'); } return vozOn; }
function botaoVoz(el){ if (!el) return; el.style.display = 'none'; return; const at = () => { el.textContent = vozOn ? '🗣️' : '🤐'; el.title = vozOn ? 'Voz ligada (toque para desligar)' : 'Voz desligada (toque para ligar)'; }; at(); el.onclick = e => { e.stopPropagation(); alternarVoz(); at(); }; }
"""


def palco3d(dados, altura=420):
    dados = dict(dados)
    dados.setdefault("noite", dados.get("lugar") in ("bar", "cobertura"))
    _dj = json.dumps(dados, ensure_ascii=False).replace("</", "<\\/")
    pag = (f"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
           f"<style>{VIDA3D_CSS}</style>{THREE_HEAD}</head><body><div id='w' style='height:{altura}px'><canvas id='c'></canvas>"
           f"<div id='vinheta'></div><div id='grao'></div><div id='local'></div><div id='cine'></div><div id='dlg'></div></div><script>const D = {_dj};</script>"
           f"<button id='voz' style='position:fixed;top:6px;right:6px;z-index:20;border:none;border-radius:10px;padding:5px 8px;font-size:16px;background:rgba(0,0,0,.5);color:#fff;cursor:pointer'>🗣️</button>"
           f"<script>{VOZ_JS}\nbotaoVoz(document.getElementById('voz'));</script><script>{VIDA3D_JS}</script></body></html>")
    jogo_html(pag, altura + 8)


def vida_hall():
    hall = S.get("vida_hall", [])
    if not hall:
        return
    st.markdown("#### 🏛️ Hall da Fama")
    for i, h in enumerate(sorted(hall, key=lambda h: -h["pts"])[:10], 1):
        medalha = {1: "🥇", 2: "🥈", 3: "🥉"}.get(i, f"{i}º")
        st.markdown(f"{medalha} **{h['pts']} pts**: {h['empresa']} ({h['ramo']}) · {h['fase']} · "
                    f"{h['meses']} meses · *{h['titulo']}* · {h['fim']}")


