def casa_quiz_iniciar(e, pr):
    """Prova do líder: 10 perguntas fáceis, 2 minutos. Cada agente tem o seu ritmo e a sua taxa de acerto, e o placar anda ao vivo."""
    pr.update(perg=random.sample(range(len(CASA_PERGUNTAS)), 10), resp=[], t0=None, fim=False, dur=120)
    linhas = {}
    for x in casa_vivos(e, False):
        p = e["parts"][x]
        acerto = min(.93, .58 + p["intel"]/320 + (.05 if p["perso"] == "competitivo" else 0) - (.04 if "preguiçoso" in p.get("tracos", []) else 0))
        ritmo = random.uniform(6.5, 11.5) - p["intel"]/60 - (.8 if p["perso"] == "competitivo" else 0)
        t, tl = 0.0, []
        for _ in range(10):
            t += max(3.0, random.gauss(ritmo, 2.2))
            tl.append((round(t, 2), random.random() < acerto))
        linhas[x] = tl
    pr["npc"] = linhas


def casa_quiz_estado(pr, x, agora):
    """(acertos, respondidas) do agente x no segundo 'agora' da prova."""
    feitas = [ok for t, ok in pr["npc"][x] if t <= min(agora, pr["dur"])]
    return sum(feitas), len(feitas)


def casa_quiz_fechar(e, k):
    pr = e["prova"]
    if pr.get("fim"):
        return
    pr["fim"] = True
    meu_ac = sum(1 for qi, r, t in pr["resp"] if r == CASA_PERGUNTAS[qi][2])
    meu_t = pr["resp"][-1][2] if len(pr["resp"]) == 10 else pr["dur"]
    sc = [("eu", meu_ac, meu_t)]
    for x in pr["npc"]:
        ac, n = casa_quiz_estado(pr, x, pr["dur"])
        tf = pr["npc"][x][-1][0] if n == 10 else pr["dur"]
        sc.append((x, ac, tf))
    sc.sort(key=lambda s: (-s[1], s[2]))
    pr["placar"] = {a: f"{ac} acertos · {min(t, pr['dur']):.0f}s" for a, ac, t in sc}
    st.session_state[k + "msg"] = f"Você acertou **{meu_ac} de 10** em **{min(meu_t, pr['dur']):.0f} segundos**."
    if meu_ac == 10:
        casa_conquistar(e, "reflexo")
    casa_fim_prova(e, [a for a, _, _ in sc])


def casa_prova_quiz10(e, k):
    pr = e["prova"]
    if "npc" not in pr:
        casa_quiz_iniciar(e, pr)
    if pr["t0"] is None:
        st.caption("🧠 **10 perguntas fáceis, 2 minutos.** Todo mundo responde ao mesmo tempo, e do lado você acompanha o placar dos outros. "
                   "Vence quem acertar mais; no empate, quem terminou mais rápido.")
        if st.button("▶️ Começar a prova", type="primary", key=k + "qz_ini", use_container_width=True):
            pr["t0"] = time.time()
            st.rerun()
        return
    agora = time.time() - pr["t0"]
    if agora >= pr["dur"] or len(pr["resp"]) >= 10:
        casa_quiz_fechar(e, k)
        st.rerun()
    c1, c2 = st.columns([3, 2])
    with c1:
        i = len(pr["resp"])
        qi = pr["perg"][i]
        q, ops, _ = CASA_PERGUNTAS[qi]
        st.markdown(f"**Pergunta {i + 1} de 10**")
        st.markdown(f"<div class='casa-card' style='font-size:1.15rem;font-weight:800'>{q}</div>", unsafe_allow_html=True)
        b = st.columns(2)
        for j, op in enumerate(ops):
            if b[j % 2].button(op, key=f"{k}qz{i}_{j}", use_container_width=True):
                pr["resp"].append((qi, j, round(time.time() - pr["t0"], 2)))
                if len(pr["resp"]) >= 10:
                    casa_quiz_fechar(e, k)
                st.rerun()
        if pr["resp"]:
            ult = pr["resp"][-1]
            st.caption("✅ Acertou a anterior!" if ult[1] == CASA_PERGUNTAS[ult[0]][2] else f"❌ Errou a anterior. Era: {CASA_PERGUNTAS[ult[0]][1][CASA_PERGUNTAS[ult[0]][2]]}")
    with c2:
        @st.fragment(run_every=1)
        def placar():
            ag = time.time() - pr["t0"]
            if ag >= pr["dur"] and not pr.get("fim"):
                st.rerun(scope="app")
            resta = max(0, pr["dur"] - ag)
            st.markdown(f"**⏱️ {int(resta)//60}:{int(resta) % 60:02d}**")
            st.progress(min(1.0, ag/pr["dur"]))
            meu = sum(1 for qi2, r, t in pr["resp"] if r == CASA_PERGUNTAS[qi2][2])
            linhas = [("Você", meu, len(pr["resp"]))] + [(casa_nome(e, x),) + casa_quiz_estado(pr, x, ag) for x in pr["npc"]]
            linhas.sort(key=lambda l: (-l[1], -l[2]))
            st.markdown("**📊 Placar ao vivo**")
            for nm, ac, n in linhas:
                eu = nm == "Você"
                st.markdown(f"{'🟡 ' if eu else ''}{'**' if eu else ''}{nm}{'**' if eu else ''}: **{ac}** acerto{'s' if ac != 1 else ''} até agora "
                            f"<span style='opacity:.6;font-size:.8rem'>({n}/10 respondidas)</span>", unsafe_allow_html=True)
        placar()



def casa_clamp(v, a=0, b=100):
    return max(a, min(b, v))


CASA_CABELO_COR = [("#111111", 5), ("#2b1d14", 6), ("#5a3a22", 5), ("#8d5524", 3), ("#e6c27a", 4), ("#f5e6b3", 2), ("#b5512b", 2), ("#d81b60", .6), ("#3949ab", .5), ("#bdbdbd", .4)]
CASA_PELES = ["#ffe0bd", "#ffdbac", "#f1c27d", "#e0ac69", "#c68642", "#a0662f", "#8d5524", "#6b4226", "#5c3a21", "#3f2a1d"]


def casa_peso(rng, pares):
    tot = sum(p for _, p in pares)
    r = rng.uniform(0, tot)
    for v, p in pares:
        r -= p
        if r <= 0:
            return v
    return pares[-1][0]


CASA_ROSTOS = ["oval", "redondo", "longo", "quadrado", "fino", "coracao", "bochechudo"]
CASA_CAB_EXTRA = {"colmeia": "Colmeia altíssima", "espetado": "Espetado", "topete": "Topete gigante", "algodao": "Nuvem de algodão", "chifrinhos": "Dois coquinhos"}


def casa_look(sexo, idade, rng, perso=None):
    """Visual variado: tipos de corpo, tatuagens, loiras/morenas/ruivas, cabelos coloridos, barbas e acessórios."""
    F = sexo == "F"
    corpo = casa_peso(rng, [("curvilinea", 4), ("atletica", 3), ("magra", 2), ("plus", 1.2), ("bombada", .8)] if F else [("musculoso", 3), ("atletico", 2.6), ("magro", 1.4), ("forte", 1.3), ("bombado", 2), ("barrigudo", 1.2)])
    if perso in ("competitivo", "arrogante", "explosivo") and rng.random() < .5:
        corpo = "atletica" if F else "musculoso"
    cab = casa_peso(rng, [("liso", 4), ("ondulado", 3), ("cacheado", 2.5), ("black", 1.2), ("rabo", 1.5), ("coque", 1), ("trancas", 1), ("franja", 1),
                          ("colmeia", 1.1), ("algodao", .9), ("chifrinhos", .9), ("espetado", .5)] if F
                    else [("curto", 4), ("raspado", 2.5), ("cacheado", 1.5), ("black", 1), ("moicano", .8), ("careca", .8), ("franja", .8), ("coque", .5),
                          ("espetado", 1.3), ("topete", 1.2), ("algodao", .5)])
    cab_cor = casa_peso(rng, CASA_CABELO_COR)
    if cab in CASA_CAB_EXTRA and rng.random() < .55:   # cabelo extravagante pede cor extravagante
        cab_cor = rng.choice(["#2979ff", "#ff4081", "#76ff03", "#aa00ff", "#ff9100", "#00e5ff", "#ffea00"])
    pele = rng.choice(CASA_PELES)
    tat, tat_estilo = [], rng.choice(["tribal", "floral", "geometrico"])
    if rng.random() < (.55 if perso in ("explosivo", "sedutor", "arrogante", "competitivo") else .35):
        tat = rng.choice([["fechado"], ["braco_d"], ["braco_e"], ["braco_d", "peito"], ["fechado", "perna"], ["perna"], ["braco_e", "pescoco"]])
    roupa = casa_peso(rng, [("cropped", 3), ("regata", 2.5), ("top", 2), ("vestido", 2), ("camiseta", 1.5), ("minissaia", 2.6)] if F
                      else [("regata", 3), ("camiseta", 2.5), ("camisa_aberta", 1.2), ("sem_camisa", 1.5 if corpo in ("musculoso", "atletico") else .3)])
    if tat and roupa == "camiseta":
        roupa = "regata"
    acess = []
    for a, p in (("oculos", .15), ("bone", .12 if not F else .06), ("corrente", .3 if not F else .12), ("brincos", .65 if F else .18)):
        if rng.random() < p:
            acess.append(a)
    barba = None if F else casa_peso(rng, [(None, 3), ("curta", 2.5), ("cheia", 1.5), ("cavanhaque", 1), ("bigode", .4)])
    cor = rng.choice(["#e53935", "#1e88e5", "#43a047", "#8e24aa", "#fb8c00", "#00acc1", "#d81b60", "#fafafa", "#212121", "#fdd835", "#6d4c41", "#ff7043"])
    calca = rng.choice(["#263238", "#1565c0", "#37474f", "#212121", "#5d4037", "#fafafa", "#90a4ae"])
    return dict(sexo=sexo, pele=pele, cab=cab, cab_cor=cab_cor, roupa=roupa, cor=cor, calca=calca, idade=idade, corpo=corpo, tat=tat,
                tat_estilo=tat_estilo, acess=acess, barba=barba, batom=rng.choice(["#b0405a", "#c2185b", "#8e2430", "#d4826b"]),
                tenis=rng.choice(["#fafafa", "#212121", "#e53935", "#1e88e5"]), saia=rng.choice(["#212121", "#e91e63", "#1565c0", "#fafafa", "#7b1fa2", "#c62828", "#fdd835"]), bone_cor=rng.choice(["#c62828", "#212121", "#1565c0", "#fafafa"]),
                olho=rng.choice(["#3e2723", "#3e2723", "#5d4037", "#1b5e20", "#1565c0", "#795548"]),
                rosto=rng.choice(CASA_ROSTOS), nariz=rng.randrange(4),
                altura=round(rng.uniform(.88, 1.03) if F else rng.uniform(.93, 1.1), 3))


def casa_look_jogador(sexo, rng):
    """Visual do jogador: sem ambiguidade de gênero (homem com cara de homem, mulher com cara de mulher)."""
    L = casa_look(sexo, 27, rng)
    if sexo == "M":
        L["cab"] = rng.choice(["curto", "curto", "raspado", "cacheado", "black", "moicano"])
        L["acess"] = [a for a in L["acess"] if a != "brincos"]
        L["corpo"] = rng.choice(["musculoso", "atletico", "atletico", "forte"])
        if L["roupa"] not in ("regata", "camiseta", "camisa_aberta", "sem_camisa"):
            L["roupa"] = "camiseta"
        L["barba"] = L.get("barba") or rng.choice([None, "curta", "curta", "cheia"])
    else:
        L["cab"] = rng.choice(["liso", "ondulado", "cacheado", "rabo", "trancas", "black"])
        L["barba"] = None
        if "brincos" not in L["acess"]:
            L["acess"] = L["acess"] + ["brincos"]
    return L


def casa_sexo_no_texto(txt):
    """'sou o Orlando' -> M; 'sou a Ana' -> F; sem pista -> None."""
    import re
    t = (txt or "").lower()
    if re.search(r"\b(sou o|eu sou o|o meu nome|sou um cara|sou homem|tô pronto|estou pronto|animado)\b", t):
        return "M"
    if re.search(r"\b(sou a|eu sou a|sou uma mulher|sou mulher|tô pronta|estou pronta|animada)\b", t):
        return "F"
    return None


def casa_look_desc(L):
    """Descrição curta do visual (usada na apresentação e nos cartões)."""
    corpo = {"curvilinea": "curvilínea", "atletica": "atlética", "magra": "magra", "plus": "plus size", "musculoso": "musculoso", "atletico": "atlético", "magro": "magro", "forte": "fortão",
             "bombado": "bombado", "bombada": "bombada", "barrigudo": "barrigudo"}.get(L.get("corpo"), "")
    cor = {"#e6c27a": "loira", "#f5e6b3": "platinada", "#b5512b": "ruiva", "#d81b60": "cabelo rosa", "#3949ab": "cabelo azul", "#bdbdbd": "grisalha", "#111111": "morena", "#2b1d14": "morena"}.get(L.get("cab_cor"), "castanha")
    if L.get("sexo") == "M":
        cor = {"loira": "loiro", "platinada": "platinado", "ruiva": "ruivo", "morena": "moreno", "castanha": "castanho", "grisalha": "grisalho"}.get(cor, cor)
    t = ", tatuado" + ("a" if L.get("sexo") == "F" else "") if L.get("tat") else ""
    alt = L.get("altura") or 1
    h = (", alt" + ("a" if L.get("sexo") == "F" else "o")) if alt >= (1.0 if L.get("sexo") == "F" else 1.065) else (", baixinh" + ("a" if L.get("sexo") == "F" else "o")) if alt <= (.91 if L.get("sexo") == "F" else .955) else ""
    return f"{cor}, {corpo}{h}{t}"


CASA_QUARTOS = [("🌸", "Quarto Rosa"), ("🌊", "Quarto Azul"), ("🌿", "Quarto Verde")]


def casa_nova(nome, sexo, n=5):
    """Temporada de 6 pessoas (o participante + 5 agentes): 3 homens e 3 mulheres, uma dupla (homem e mulher) em cada um dos 3 quartos."""
    rng = random.Random()
    perso = list(CASA_PERSO)
    rng.shuffle(perso)
    nomes = CASA_NOMES[:]
    rng.shuffle(nomes)
    elenco = None
    if n == 5:
        mesmo = [x for x in nomes if x[1] == sexo][:2]
        outro = [x for x in nomes if x[1] != sexo][:3]
        nomes = [outro[0], mesmo[0], outro[1], mesmo[1], outro[2]]
        # o elenco vem dos personagens com história; quem você ainda não conheceu tem mais chance de aparecer
        alb = S.get("casa_album", {})
        pool = [l for l in CASA_LENDAS if l["nome"].lower() != (nome or "").strip().lower()]
        def sorteia(sx, q):
            cands = [l for l in pool if l["sexo"] == sx]
            esc = []
            while cands and len(esc) < q:
                w = [1 if l["id"] in alb else 3.5 for l in cands]
                c = rng.choices(cands, weights=w)[0]
                esc.append(c)
                cands.remove(c)
            return esc
        m_, o_ = sorteia(sexo, 2), sorteia("F" if sexo == "M" else "M", 3)
        if len(m_) == 2 and len(o_) == 3:
            elenco = [o_[0], m_[0], o_[1], m_[1], o_[2]]
    parts = {}
    for i in range(n):
        nm, sx = nomes[i]
        pk, idade, pid = perso[i], rng.randint(21, 38), f"p{i}"
        if elenco:
            nm, sx, pk, idade = elenco[i]["nome"], elenco[i]["sexo"], elenco[i]["perso"], elenco[i]["idade"]
        base = CASA_PERSO[pk][2]
        p = dict(id=pid, nome=nm, sexo=sx, idade=idade, perso=pk, vivo=True, revelado=False, conversas=0, memoria=[], provas=0, tracos=rng.sample(list(CASA_TRACOS), 2),
                 look=casa_look(sx, idade, random.Random(f"{pid}{nm}{rng.random()}"), pk))
        if elenco:
            p["lenda"], p["tracos"], p["cap_rev"] = elenco[i]["id"], list(elenco[i]["tracos"]), 0
            if CASA_LENDA_EXTRA.get(elenco[i]["id"]):
                p["tracos"].append(CASA_LENDA_EXTRA[elenco[i]["id"]])
        for k, v in base.items():
            p[k] = casa_clamp(v + rng.randint(-8, 8))
        p["pop"] = casa_clamp(rng.randint(36, 64) + {"popular": 4, "engracado": 3, "explosivo": -2}.get(pk, 0))
        parts[pid] = p
    ids = list(parts) + ["eu"]
    rel = {a: {b: dict(amz=50 + rng.randint(-14, 14), conf=45 + rng.randint(-12, 12)) for b in ids if b != a} for a in ids}
    for a in parts:  # o arrogante começa antipático, o popular e o engraçado começam queridos
        for b in ids:
            if b == a:
                continue
            if parts[a]["perso"] == "arrogante":
                rel[b][a]["amz"] -= 6
            if parts[a]["perso"] in ("popular", "engracado"):
                rel[b][a]["amz"] += 10
    return dict(jogador=nome, sexo=sexo, look=casa_look_jogador(sexo, random.Random(nome + sexo)), pop=52, vivo=True,
                parts=parts, rel=rel, semana=1, fase="abertura", lider=None, anjo=None, imune=None, paredao=[], indicado=None,
                acoes=3, aliados=[], planos=[], segredos=[], diario=[], chats={}, eliminados=[], cena=None, prova=None, votos=[],
                quarto_usado=False, bigfone=None, festa=False, vencedor=None, defesa={}, duelo=None, resultado=None, conf_semana=0,
                grupos=[], casais=[], traicoes=[], resp_mod={}, objetivos={}, vinganca={}, propostas={}, rep_feita=False, gid=0, flertes={}, obj_vistos=[],
                rep_planejada=rng.random() < .45 and n > 5, sobrev={}, tour_feitos=[],
                tour_semanas=[2] if n <= 5 else sorted(rng.sample(range(2, 6 if n <= 8 else 8), 2)),
                provas_ordem=rng.sample(["quiz", "resistencia", "reflexo", "sorte", "equilibrio", "memoria"], 6),
                quartos=[])


def casa_montar_quartos(ids, parts, sexo):
    """Um casal (homem + mulher) em cada quarto; você fica com p0, que é do sexo oposto."""
    outro = [x for x in ids if parts[x]["sexo"] != sexo]
    mesmo = [x for x in ids if parts[x]["sexo"] == sexo]
    pares = [["eu", outro[0]]] + [[mesmo[i], outro[i + 1]] for i in range(min(len(mesmo), len(outro) - 1))]
    return [dict(emo=em, nome=nm, membros=pr) for (em, nm), pr in zip(CASA_QUARTOS, pares)]


def casa_quarto_de(e, pid):
    return next((q for q in e.get("quartos", []) if pid in q["membros"]), None)


def casa_quartos_ui(e):
    if not e.get("quartos"):
        return
    st.markdown("#### 🛏️ Os quartos (uma dupla em cada)")
    for q in e["quartos"]:
        st.markdown(f"**{q['emo']} {q['nome']}:** " + " e ".join(("**Você**" if m == "eu" else casa_nome(e, m)) + ("" if m == "eu" or e["parts"][m]["vivo"] else " (eliminado)")
                                                              for m in q["membros"]))


def casa_nome(e, pid):
    return (e.get("jogador") or "Você") if pid == "eu" else e["parts"][pid]["nome"]   # o participante é chamado pelo nome, nunca de "você"


def casa_vivos(e, com_jogador=True):
    v = [p for p, d in e["parts"].items() if d["vivo"]]
    return v + (["eu"] if com_jogador and e["vivo"] else [])


def casa_mudar(e, a, b, amz=0, conf=0, mutuo=False):
    if a == b:
        return
    r = e["rel"][a][b]
    r["amz"] = casa_clamp(r["amz"] + amz)
    r["conf"] = casa_clamp(r["conf"] + conf)
    if mutuo:
        casa_mudar(e, b, a, amz, conf)


def casa_op(e, a, b):
    if a == b:
        return 100
    r = e["rel"][a][b]
    return r["amz"]*.6 + r["conf"]*.4


def casa_lembrar(e, pid, txt):
    if pid in e["parts"]:
        m = e["parts"][pid]["memoria"]
        m.append(f"Semana {e['semana']}: {txt}")
        del m[:-10]


def casa_sem_voce(e, txt):
    """Narração e manchetes chamam o participante pelo nome: 'Orlando é o novo líder', nunca 'Você é o novo líder'."""
    import re
    J = e.get("jogador")
    if not J or not txt:
        return txt
    txt = re.sub(r"\bVocê\b", J, txt)
    txt = re.sub(r"\bvocê\b", J, txt)
    return txt


def casa_reg(e, txt):
    e["diario"].append((e["semana"], casa_sem_voce(e, txt)))


def casa_pop(e, pid, d):
    if pid == "eu":
        e["pop"] = casa_clamp(e["pop"] + d)
    else:
        e["parts"][pid]["pop"] = casa_clamp(e["parts"][pid]["pop"] + d)


def casa_popv(e, pid):
    return e["pop"] if pid == "eu" else e["parts"][pid]["pop"]


def casa_rotulo(e, pid):
    r = e["rel"][pid]["eu"]
    if pid in e["aliados"]:
        return "🤝 Aliado"
    if r["amz"] >= 70:
        return "💚 Amigo"
    if r["amz"] <= 28:
        return "😠 Rival"
    if r["conf"] <= 32:
        return "🤨 Desconfiado"
    return "😐 Neutro"


CASA_VOC_F2M = {"mana": "mano", "maninha": "maninho", "miga": "migo", "amiga": "amigo", "amigona": "amigão", "gata": "gato", "gatinha": "gatinho", "menina": "menino",
                "querida": "querido", "linda": "lindo", "bonita": "bonito", "amada": "amado", "princesa": "príncipe", "mocinha": "mocinho", "garota": "garoto",
                "mulher": "homem", "minha filha": "meu filho", "fofa": "fofo", "bebê": "bebê", "parceira": "parceiro", "colega": "colega", "irmã": "irmão", "mermã": "mermão"}
CASA_VOC_M2F = {v: k for k, v in CASA_VOC_F2M.items() if v not in ("bebê", "colega", "homem")}
CASA_VOC_M2F.update({"mermão": "mermã", "cara": "amiga", "brother": "amiga", "parça": "amiga", "rapaz": "moça", "véi": "véia", "meu rei": "minha rainha"})


def casa_vocativo(txt, F):
    """Quando alguém chama o participante por apelido ('mana', 'amigo', 'gata'...), o apelido segue o sexo de quem está jogando."""
    import re
    mapa = CASA_VOC_M2F if F else CASA_VOC_F2M
    mapa = {k: v for k, v in mapa.items() if k != v}
    alt = "|".join(sorted((re.escape(k) for k in mapa), key=len, reverse=True))
    def troca(m):
        w = m.group(2)
        n = mapa.get(w.lower(), w)
        n = n.capitalize() if w[:1].isupper() else n
        return m.group(1) + n
    # só quando é vocativo: no começo da frase ou entre vírgulas/pontuação ("Ô mana,", ", amiga!", "minha linda.")
    pre = r"(^|[,!?.…;:]\s*|\b(?:[ôÔoO]|ai|Ai|oi|Oi|olha|Olha|né|ué|vem|Vem|minha|Minha|meu|Meu|e aí|E aí)\s+)"
    txt = re.sub(pre + r"(" + alt + r")(?=\s*[,!?.…;:]|\s*$)", troca, txt, flags=re.I)
    if not F:
        txt = re.sub(r"\b([Mm])ana\b", lambda m: m.group(1) + "ano", txt)   # 'mana' nunca é para homem
    return txt


def casa_gen(e, txt, quem=None):
    """Concordância de gênero: fala dirigida ao jogador segue o sexo dele; fala de quem fala segue o sexo de quem fala."""
    import re
    if not txt:
        return txt
    F = e.get("sexo") == "F"
    if F:
        for a, b in (("Seja bem-vindo", "Seja bem-vinda"), ("Bem-vindo ao", "Bem-vinda ao"), ("chegou mais um!", "chegou mais uma!"),
                     ("Você é o novo líder", "Você é a nova líder"), ("VOCÊ É O LÍDER", "VOCÊ É A LÍDER"), ("Você foi eliminado", "Você foi eliminada")):
            txt = txt.replace(a, b)
    txt = casa_vocativo(txt, F)
    txt = re.sub(r"\b([Vv])ocê, você\b", lambda m: m.group(1) + "ocê", txt)
    txt = re.sub(r"(?<=[a-zà-ÿ]), Você([!?.,])", r", você\1", txt)   # 'Você, você nem...' -> 'Você nem...'
    txt = re.sub(r"\b(\w+?)o\(a\)", lambda m: m.group(1) + ("a" if F else "o"), txt)
    txt = re.sub(r"\b(\w+?)ã\(o\)", lambda m: m.group(1) + ("ã" if F else "ão"), txt)
    fala_f = (quem in e.get("parts", {}) and e["parts"][quem]["sexo"] == "F") or (quem in ("eu", "Você", e.get("jogador")) and F)
    if fala_f:
        for a, b in (("obrigado", "obrigada"), ("Obrigado", "Obrigada"), ("sozinho", "sozinha"), ("apaixonado", "apaixonada"), ("cansado", "cansada"),
                     ("o campeão", "a campeã"), ("preparado", "preparada"), ("ligado", "ligada"), ("nervoso", "nervosa"), ("Ansioso", "Ansiosa"), ("quieto", "quieta"), ("fui adotado", "fui adotada"),
                     ("Fui chamado pra ser padrinho", "Fui chamada pra ser madrinha"), ("quero ser pai", "quero ser mãe"),
                     ("resolvo sozinho", "resolvo sozinha")):
            txt = re.sub(r"\b" + a + r"\b", b, txt)
    return txt


def casa_cena(e, lugar, npcs, texto, quem=None, titulo=None, capitulo=None, saida=False, enc=None, eu=False, var=None, extra=None, maxn=5):
    e["cena"] = casa_cena_dict(e, lugar, npcs, texto, quem, titulo, capitulo, saida, enc, eu, var, extra, maxn)


def casa_cena_dict(e, lugar, npcs, texto, quem=None, titulo=None, capitulo=None, saida=False, enc=None, eu=False, var=None, extra=None, maxn=5):
    texto, titulo = casa_gen(e, texto, quem), casa_sem_voce(e, casa_gen(e, titulo))
    if quem not in e.get("parts", {}) and quem not in ("eu", "Você", e.get("jogador")):   # narração e apresentador: o participante é chamado pelo nome
        texto = casa_sem_voce(e, texto)
    sem_var = e.pop("_sem_variar", False)
    if quem in e.get("parts", {}) and texto and not sem_var:
        texto = casa_variar(e, texto, quem)   # ninguém repete a mesma frase igualzinha
    return dict(lugar=lugar, npcs=[n for n in npcs if n in e["parts"]][:maxn], texto=texto, quem=quem, titulo=titulo, capitulo=capitulo,
                     enc=enc or ("saida" if saida else "grupo"), eu=eu, var=var, semente=random.randrange(9), extra=extra or {}, cid=f"{time.time():.3f}")


def palco_casa_html(dados, altura=420, alt_css=None):
    h_css = alt_css or f"{altura}px"
    _dj = json.dumps(dados, ensure_ascii=False).replace("</", "<\\/")
    js = VIDA3D_JS.split("// ---------------------------------------------------------- montar")[0] + CASA3D_JS
    return (f"<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
           f"<style>{VIDA3D_CSS}</style>{THREE_HEAD}</head><body><div id='w' style='height:{h_css}'><canvas id='c'></canvas>"
           f"<div id='vinheta'></div><div id='grao'></div><div id='local'></div><div id='cine'></div><div id='dlg'></div></div><script>const D = {_dj};</script>"
           f"<button id='voz' style='position:fixed;top:6px;right:6px;z-index:20;border:none;border-radius:10px;padding:5px 8px;font-size:16px;background:rgba(0,0,0,.5);color:#fff;cursor:pointer'>🗣️</button>"
           f"<script>{VOZ_JS}</script><script>{CASA_VOZ_JS}</script><script>{js}</script></body></html>")


def palco_casa(dados, altura=420):
    jogo_html(palco_casa_html(dados, altura), altura + 8)


CASA_VOZ_JS = r"""
// vozes dos participantes da Casa (só eles falam; não há narrador)
let casaVoz = true; try { casaVoz = localStorage.getItem('casa_voz') !== '0'; } catch (e) {}
const _FEM = /maria|francisca|luciana|thalita|raquel|fernanda|joana|catarina|let[ií]cia|vit[oó]ria|brenda|elza|giovanna|leila|manuela|yara|camila|ana\b|female|feminina|mulher|helena|beatriz|clara|julia|j[uú]lia|isabela|larissa|google portugu[eê]s do brasil/i;
const _MAS = /daniel|ant[oô]nio|felipe|f[aá]bio|duarte|j[uú]lio|humberto|nicolau|val[eé]rio|donato|male|masculin|homem|jo[aã]o|pedro|lucas|ricardo|cristiano|paulo/i;
function vozesPt(){ let v = []; try { v = speechSynthesis.getVoices(); } catch (e) {} const l = v.filter(x => /^pt[-_]BR/i.test(x.lang)); return l.length ? l : v.filter(x => /^pt/i.test(x.lang)); }
// emoção da fala: vem da cena (o.emo) ou é lida no próprio texto
function emoTexto(t){ t = (t || '').toLowerCase();
  if (/(hahaha|kkk|rsrs|adorei|que delícia|que bom|ganhei|uhuu|eba|demais!|que legal)/.test(t)) return 'alegre';
  if (/(parabéns|valendo|grande final|campeã|campeão|aplausos|brasil, )/.test(t)) return 'empolgado';
  if (/(saudade|chorei|morreu|morte|doente|sozinh|triste|medo|perdi|dói|doeu|culpa|abandon|hospital|luto)/.test(t)) return 'triste';
  if (/(absurdo|raiva|cala a boca|não aguento|mentiros|falso|traíra|ridícul|sai daqui|chega!)/.test(t)) return 'bravo';
  if (/(calma|devagar|respira|tá tudo bem|fica tranquil)/.test(t)) return 'calmo';
  return 'neutro'; }
const EMO_VOZ = {alegre: [.12, .08], empolgado: [.16, .14], triste: [-.14, -.2], bravo: [-.06, .12], calmo: [-.04, -.12], neutro: [0, 0], ironico: [.05, -.04]};
function vozDoSexo(sexo, h){ const l = vozesPt(); if (!l.length) return [null, false];
  const m = l.filter(v => _MAS.test(v.name) && !_FEM.test(v.name)), f = l.filter(v => _FEM.test(v.name) && !_MAS.test(v.name));
  const lista = sexo === 'M' ? m : f;
  if (lista.length) return [lista[Math.abs(h || 0) % lista.length], true];
  return [(sexo === 'M' ? (l.find(v => !_FEM.test(v.name)) || l[0]) : (f[0] || l[0])), false]; }
function falarCasa(txt, o = {}){ if (!casaVoz || !('speechSynthesis' in window) || !txt) return null; window.__vozOn = true;
  txt = String(txt).replace(/<[^>]*>/g, ' ').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{FE0F}\u{200D}#*]/gu, '').replace(/\s+/g, ' ').trim().slice(0, 320);
  if (!txt) return null;
  try { speechSynthesis.cancel(); try { speechSynthesis.resume(); } catch (e2) {} const u = new SpeechSynthesisUtterance(txt); u.lang = 'pt-BR'; const h = Math.abs(o.voz || 0);
    const host = o.host || /apresentador/i.test(o.quem || '');
    const [ed, er] = EMO_VOZ[o.emo || emoTexto(txt)] || [0, 0];
    if (host) {   // o apresentador tem voz própria: grave, pausada, de locutor, diferente de todos os participantes
      const l = vozesPt(), m = l.filter(v => _MAS.test(v.name) && !_FEM.test(v.name));
      const v = m.length ? m[m.length - 1] : (l.find(v => !_FEM.test(v.name)) || l[0]); if (v) u.voice = v;
      u.pitch = Math.max(.1, (m.length ? .62 : .42) + ed*.5); u.rate = Math.max(.7, .97 + er*.6);
    } else {
      // cada participante tem uma combinação própria de voz, tom e ritmo (dois números do nome mexem em coisas diferentes)
      const h2 = Math.floor(h/7), l = vozesPt(), m = l.filter(v => _MAS.test(v.name) && !_FEM.test(v.name)), mUso = m.length > 1 ? m.slice(0, -1) : m;
      let [v, certa] = vozDoSexo(o.sexo, h); if (o.sexo === 'M' && mUso.length) { v = mUso[h % mUso.length]; certa = true; } if (v) u.voice = v;
      if (o.sexo === 'M') u.pitch = certa ? .84 + (h % 6)*.045 : .5 + (h % 5)*.05; else if (o.sexo === 'F') u.pitch = certa ? 1.0 + (h % 6)*.06 : 1.18 + (h % 5)*.07; else u.pitch = 1;
      u.rate = 1.0 + (h2 % 6)*.045;
      u.pitch = Math.max(.1, Math.min(2, u.pitch + ed)); u.rate = Math.max(.7, Math.min(1.6, u.rate + er));
    }
    setTimeout(() => { try { speechSynthesis.speak(u); } catch (e3) {} }, 140); return u; } catch (e) { return null; } }
// o Chrome às vezes "dorme" no meio de falas longas: um toque de resume a cada 8 s evita que o som suma
setInterval(() => { try { if (speechSynthesis.speaking && !speechSynthesis.paused) { speechSynthesis.pause(); speechSynthesis.resume(); } } catch (e) {} }, 8000);
try { speechSynthesis.getVoices(); speechSynthesis.addEventListener('voiceschanged', () => {}); } catch (e) {}
addEventListener('pointerdown', () => { try { speechSynthesis.resume(); } catch (e) {} });
(() => { const b = document.getElementById('voz'); if (!b) return; if (typeof D !== 'undefined' && D.semBotao) { b.style.display = 'none'; return; } b.style.display = '';
  const at = () => { b.textContent = casaVoz ? '🗣️' : '🤐'; b.title = casaVoz ? 'Vozes dos participantes ligadas (toque para desligar)' : 'Vozes desligadas (toque para ligar)'; }; at();
  b.onclick = e => { e.stopPropagation(); casaVoz = !casaVoz; try { localStorage.setItem('casa_voz', casaVoz ? '1' : '0'); } catch (e2) {} try { if (!casaVoz) speechSynthesis.cancel(); } catch (e2) {}
    if (casaVoz) { try { localStorage.removeItem('casa_ult_fala'); } catch (e2) {} } at(); }; })();
"""


def casa_dados(e, c):
    P = e["parts"]
    foco = [dict(P[p]["look"], nome=P[p]["nome"]) for p in c["npcs"]]
    fundo = []
    if c["lugar"] in ("reality_sala", "reality_cozinha", "reality_quarto", "reality_piscina") and c.get("enc") not in ("festa", "eliminacao", "bigfone") \
            and not c.get("extra", {}).get("cenario") and e.get("fase") not in ("rodada",):   # conversa cara a cara: ninguém na frente da câmera
        resto = [p for p in casa_vivos(e, False) if p not in c["npcs"]]
        rr = random.Random(f"{e['semana']}{c['lugar']}{c.get('semente', 0)}")
        fundo = [dict(P[p]["look"], nome=P[p]["nome"]) for p in rr.sample(resto, min(4, len(resto)))]
    q = c.get("quem")
    quem = P[q]["nome"] if q in P else (None if q in (None, "eu") else q)
    noite = c["lugar"] in ("reality_piscina", "paredao", "confessionario") and e["fase"] in ("convivencia", "paredao", "eliminacao", "defesa", "votacao_res", "final", "fim")
    vf = q in P or q == "Apresentador"   # vozes só para as IAs e o apresentador; o participante real aparece só em texto
    sf = P[q]["sexo"] if q in P else "M" if q == "Apresentador" else None
    return dict(cid=c.get("cid", ""), vozFala=vf, sexoFala=sf, lugar=c["lugar"], enc=c.get("enc", "grupo"), foco=foco, eu=dict(e["look"], nome=e["jogador"]) if c.get("eu") else None,
                fundo=fundo, semente=c.get("semente", 0), variante=c.get("var"), local="🏠 " + CASA_LUGAR.get(c["lugar"], "Casa"),
                quem=quem, titulo=c.get("titulo"), texto=md_html(c["texto"]), capitulo=c.get("capitulo"), noite=noite or c["lugar"] == "saida_rua" or bool(c.get("extra", {}).get("noite")),
                host=CASA_HOST, **{k2: v for k2, v in c.get("extra", {}).items() if k2 != "noite"})


def casa_palco(e, altura=400):
    c = e.get("cena") or dict(lugar="reality_sala", npcs=[], texto="", quem=None)
    d = casa_dados(e, c)
    if c.get("prox"):   # a cena seguinte já vem pronta: quando a votação acaba, todos vão para a sala sem precisar clicar
        d["proxHtml"] = palco_casa_html(casa_dados(e, c["prox"]), altura)
    if c.get("prox_split"):   # depois do primeiro encontro: a tela se divide em 3, um quarto em cada parte
        d["proxHtml"] = casa_quartos_split_html(e, altura)
    palco_casa(d, altura)


