def _busca_norm(t):
    import unicodedata
    return "".join(c for c in unicodedata.normalize("NFD", (t or "").lower()) if unicodedata.category(c) != "Mn")


def busca_jogos(texto, nomes):
    """Filtra os jogos pelo que a pessoa digitou. Os tipos de jogo (cartas, tiro, corrida...) procuram no nome;
    a palavra digitada também vale se aparecer inteira na explicação do jogo."""
    import re as _re
    q = _busca_norm(texto).strip()
    if not q:
        return nomes
    cat_de = {n: c for c, d in CATEGORIAS.items() for n in d}
    nome_n = {n: _busca_norm(n + " " + cat_de.get(n, "")) for n in nomes}
    expl = {n: _busca_norm(INSTRUCOES.get(n, "") if isinstance(INSTRUCOES.get(n, ""), str) else "") for n in nomes}
    def sinonimos(t):
        v = set()
        for tipo, lista in BUSCA_TIPOS.items():
            tn = _busca_norm(tipo)
            if tn.startswith(t[:5]) or t.startswith(tn[:5]):
                v.update(lista)
        return v
    def casa(n, t):
        if t in nome_n[n] or any(s_ in nome_n[n] for s_ in sinonimos(t)):
            return True
        return len(t) >= 4 and _re.search(r"\b" + _re.escape(t) + r"\b", expl[n]) is not None
    if any(_busca_norm(tp).startswith(q) or q.startswith(_busca_norm(tp)) for tp in BUSCA_TIPOS) and " " in q:
        return [n for n in nomes if casa(n, q)]
    return [n for n in nomes if all(casa(n, t) for t in q.replace(",", " ").split() if len(t) > 1)]


